const items = $input.all()[0].json.near_earth_objects;
let results = [];

for (const date in items) {
  for (const ast of items[date]) {
    // Safely extract values
    const dia_min = ast.estimated_diameter?.meters?.estimated_diameter_min || 0;
    const dia_max = ast.estimated_diameter?.meters?.estimated_diameter_max || 100;
    const dia = (dia_min + dia_max) / 2;

    const approach = ast.close_approach_data && ast.close_approach_data.length > 0 
      ? ast.close_approach_data[0] 
      : null;

    const vel = approach ? parseFloat(approach.relative_velocity.kilometers_per_hour) : 0;
    const dist = approach ? parseFloat(approach.miss_distance.kilometers) : 0;
    const haz = ast.is_potentially_hazardous_asteroid || false;

    results.push({
      name: ast.name,
      diameter: dia,
      velocity: vel,
      miss_distance: dist,
      hazardous: haz,
      assessment: haz ? "CRITICAL RISK: Object flagged as potentially hazardous by NASA CNEOS." : "Standard orbital transit. No immediate threat.",
      date: approach ? approach.close_approach_date : "Unknown"
    });
  }
}

return [{ json: { asteroids: results } }];
